            if r1 == r2:
                for c in range(min(c1, c2), max(c1, c2) + 1):
                    out[r1][c] = color
            elif c1 == c2:
                for r in range(min(r1, r2), max(r1, r2) + 1):
                    out[r][c1] = color

    # Complete one-cell gaps along rows and columns.
    before = [row[:] for row in out]
    for r in range(h):
        for c in range(1, w - 1):
            if before[r][c - 1] == before[r][c + 1] and before[r][c - 1] not in (0, 2, 4):
